								{ offset: 1, color: "rgba(64, 175, 255, 0.10)" },
							]),
						},
					},
					{
						value: 5800,
						itemStyle: {
							color: new graphic.LinearGradient(0, 0, 0, 1, [
								{ offset: 0, color: "rgba(25, 255, 198, 1)" },
								{ offset: 1, color: "rgba(0, 204, 187, 0.10)" },
