					{
						value: 5000,
						itemStyle: {
							color: new graphic.LinearGradient(0, 0, 0, 1, [
								{ offset: 0, color: "rgba(64, 175, 255, 1)" },
								{ offset: 1, color: "rgba(64, 175, 255, 0.10)" },
							]),
						},
					},
				],
			},
			{
				// 柱顶光点：custom 系列把 10×10 图标贴到 (类目, 数值) 的像素位，
