			borderColor: "#999999",
			textStyle: {
				color: "#ffffff",
				fontSize: 10,
				// 156px 行高远超字号，会把多行 tooltip 撑得很高；当前内容只有一行，影响不明显
				lineHeight: 156,
			},
		},
		// 全局两色兜底；主条实际用每项的渐变，槽道用 "none" 填充，所以这两色基本不生效
		color: ["#6BC7F6", "#44E6A2"],
		xAxis: [
			{
				// 数值轴；interval 写 0 沿用模板习惯，刻度实际由数据范围自动划分
