						},
					},
				],
				type: "bar",
				barWidth: 7,
				yAxisIndex: 0,
				showBackground: false,
				// z:2 保证细条压在槽道之上，否则描边框会盖住条形两端
				z: 2,
				label: {
					show: true,
					// 文字写在条形内部：柱高只有 7px，靠负的顶部 padding 把文本上提，视觉上居中于条形
					position: "middle",
