					color: "#16C1A6",
					fontSize: 12,
					// 中间那一长串空格是把「值 + 单位」推到条形右端的排版手段：
					// label 宽度默认等于条形长度，靠空格撑开而不是另加定位，因此空格数量需与卡片宽度匹配
					formatter:
						"{title|{b}}                                                                              {value|{c}}  {unit|万元}",
					// rich 分段样式：标题白、数值继承主色、单位灰，三者在同一行里各有颜色
					rich: {
