	} satisfies EChartsOption;

	/**
	 * 建 ECharts 实例并写入 option，同时用 ResizeObserver 跟随容器尺寸重绘。
	 * @returns 解绑尺寸监听的清理函数；容器 ref 未就绪时返回 undefined，调用方需 `?.` 兜底。
