			// 12 个类目全量显示会互相压字，用回调只保留第 0/2/4/6/8/11 个，
			// 末位 11 是刻意保留的，确保最后一个月一定有可读标签
			interval: (index) => [0, 2, 4, 6, 8, 11].includes(index),
		},
