							"tw:absolute tw:left-0 tw:top-0 tw:right-0 tw:bottom-0",
							"tw:flex tw:flex-col tw:z-4 tw:rotate-y-6",
						)}
					>
						{/* 大宗商品销售额 */}
						<BulkCommoditySales />
						{/* 年度经济增长点 */}
						<YearlyEconomyTrend />
