						<EconomicTrend />
						{/* 各区经济收益 */}
						<DistrictEconomicIncome />
					</div>
				</div>
				{/* 右边布局 图表 */}
				<div
					class={cn(
						"tw:w-100 tw:absolute tw:right-8 tw:top-32 tw:bottom-12",
						"tw:z-4 tw:perspective-[500px] tw:perspective-origin-center",
					)}
				>
					<div
						class={cn(
							"tw:absolute tw:left-0 tw:top-0 tw:right-0 tw:bottom-0",
