/**
 * 逐帧时钟：基于 requestAnimationFrame 驱动，每帧广播 tick(delta, elapsedTime)。
 * 被 Map3D 的 world 持有，是场景内所有自发动画（贴图滚动、旋转边框、shader 时间）的唯一时间源。
 */
import { Clock } from "three";
import EventEmitter from "./event-emitter";
import requestAnimationFrameFn from "./request-animation-frame";

export default class Time extends EventEmitter {
    private _start: number;
    private _current: number;
    private _elapsed: number;
    private _delta: number;
    /** Three.js 的 Clock，用于提供稳定、与系统时间无关的 delta / elapsed */
    private _clock: Clock;
    /** 底层 rAF 循环句柄，pause/resume 都转交给它 */
    private _raf: ReturnType<typeof requestAnimationFrameFn>;

    constructor() {
        super();
        // 构造即启动循环；需要暂停时由外部显式调用 pause（loadMap 会先暂停再等 play）
        this._start = Date.now();
        this._current = this._start;
        this._elapsed = 0;
        this._delta = 16; // 首帧前的默认值，取 16ms ≈ 60fps，避免用 0 参与除法
        this._clock = new Clock();
        this._raf = requestAnimationFrameFn(() => this.tick());
        this._raf.start();
    }
    /** 每帧被 rAF 调用：更新计时字段后向外广播 */
    tick() {
        const currentTime = Date.now();
        this._delta = currentTime - this._current;
        this._current = currentTime;
        this._elapsed = this._current - this._start;
        // 对外广播用 Clock 的 delta：它不受系统时间跳变影响，单位是秒
        const delta = this._clock.getDelta();
        const elapsedTime = this._clock.getElapsedTime();
        this.emit("tick", delta, elapsedTime);
    }
    /** 销毁：先停帧再清空订阅，避免停之前还有一帧回调打到已销毁的场景 */
    destroy() {
        this.pause();
        this.off("tick");
    }
    /** 暂停逐帧循环，切屏或页面不可见时调用 */
    pause() {
        this._raf.pause();
    }
    /** 恢复逐帧循环 */
    resume() {
        this._raf.resume();
    }
    isActive() {
        // 转发底层 rAF 的活跃状态；此处未 return，调用方拿到的是 undefined，仅供调试观察
        this._raf.isActive();
    }
}

files.src/shared/map/utils/transfrom-map-geojs:
/**
 * 把 GeoJSON 文本解析并统一成 FeatureCollection，同时把 Polygon 包成 MultiPolygon。
 *
 * 上游地图组件（BaseMap / Line / ExtrudeMap）统一按 MultiPolygon 的三层坐标结构遍历，
 * 单环 Polygon 少一层嵌套会导致取点越界，因此这里先抹平差异。
 * 经纬度顺序保持 GeoJSON 规范 [经度, 纬度]，不做翻转；平面投影由各屏的 geoProjection 负责。
 */
import type { FeatureCollection } from 'geojson'

/**
 * @param data GeoJSON 原始文本（由 FileLoader 以纯字符串加载）
 * @returns 统一为 MultiPolygon 结构的 FeatureCollection
 */
export const transfromMapGeoJSON = (data: string) => {
    const worldData = JSON.parse(data)
    const features = worldData.features
    for (let i = 0; i < features.length; i++) {
        const element = features[i]
        // 仅处理单多边形：外面再套一层数组，即 coordinates = [coordinates]
        if (["Polygon"].includes(element.geometry.type)) {
            element.geometry.coordinates = [element.geometry.coordinates]
        }
    }
    return worldData as FeatureCollection
}

files.src/shared/map/utils/uuid.ts:
/**
 * 随机字符串生成工具，用于给 CSS3D 标签的容器生成唯一类名，
 * 避免多个标签渲染器的 DOM 样式互相覆盖（见 world-core/components/label-3d.ts）。
 */

/**
 * 生成一个随机的UUID字符串
 *
 * @param len - 生成UUID的长度，默认为10；传 0 时走标准 36 位 UUID 分支
 * @param radix - 使用的字符进制数，默认为62（使用数字+大小写字母）
 * @returns 生成的UUID字符串
 */
export function uuid(len = 10, radix = 62) {
	const chars =
		"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz".split("");
	let uuid: string[] = [],
		i: number;
	// 设置实际使用的进制数
	radix = radix || chars.length;

	if (len) {
		// 根据指定长度生成随机字符串；0|x 是取整惯用法，等价于 Math.floor(x)
		for (i = 0; i < len; i++) uuid[i] = chars[0 | (Math.random() * radix)];
	} else {
		let r: number;
		// 设置UUID标准格式中的固定位置字符
		uuid[8] = uuid[13] = uuid[18] = uuid[23] = "-";
		uuid[14] = "4";
		// 生成标准UUID格式的字符串
		for (i = 0; i < 36; i++) {
			if (!uuid[i]) {
				r = 0 | (Math.random() * 16);
				// 对于第19位字符，应用特殊规则以满足UUID版本要求
				uuid[i] = chars[i === 19 ? (r & 0x3) | 0x8 : r];
			}
		}
	}

	return uuid.join("");
}

files.src/shared/map/world-core/camera.ts:
/**
 * 3D 地图相机：封装透视/正交两种投影，并绑定 OrbitControls 轨道控制。
 * 由 WorldCore 在初始化时创建并持有，渲染器与 CSS3D 标签层都直接从
 * 这里取相机实例，保证两层使用同一套视图矩阵。
 */
import {
	OrthographicCamera,
	PerspectiveCamera,
	type Scene,
	type Camera as ThreeCamera,
} from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import type { Sizes } from "../utils/sizes";
import type { WorldCoreConfig } from ".";

/**
 * 相机初始化依赖。
 */
export interface CameraConfig {
	/** 视口尺寸管理器，提供 width / height 并在窗口变化时派发 resize */
	sizes: Sizes;
	/** 相机要挂载的场景，Three.js 要求相机参与场景才能被渲染器识别 */
	scene: Scene;
	/** 用于绑定鼠标/触摸事件的原生 canvas */
	canvas: HTMLCanvasElement;
}

/** 两种投影相机的联合类型 */
type CameraInstance = PerspectiveCamera | OrthographicCamera;

/**
 * 地图相机控制器。
 * 只维护一个相机实例与一套控制器，投影方式在构造时确定后不再切换。
 * 三块大屏目前都用默认的透视投影，正交模式保留给不需要近大远小的场景。
 */
export default class Camera {
	#sizes: Sizes;
	#scene: Scene;
	#canvas: HTMLCanvasElement;
	/** 合并默认值后的配置，isOrthographic 决定投影类型 */
	#options: WorldCoreConfig;
	/** 当前相机实例，构造过程中先置空，setInstance 之后必有值 */
	#instance: CameraInstance | null = null;
	/** 轨道控制器，与相机同生命周期，destroy 时释放 */
	#controls: OrbitControls | null = null;

	/**
	 * @param config 场景、canvas 与视口尺寸
	 * @param options 投影方式，缺省为透视投影
	 */
	constructor(
		{ sizes, scene, canvas }: CameraConfig,
		options: WorldCoreConfig = { isOrthographic: false },
	) {
		this.#sizes = sizes;
		this.#scene = scene;
		this.#canvas = canvas;
		this.#options = Object.assign({ isOrthographic: false }, options);
		this.#setInstance();
	}

	/** 取相机实例，调用前请确认已完成构造 */
	get instance() {
		return this.#instance as CameraInstance;
	}

	/**
	 * 重建相机并挂回场景。
	 * 先把旧实例置空，避免后续步骤失败时留下半初始化的对象；
	 * 位置 (10, 10, 10) 只是库内的安全默认值，大屏构造完会立即用自身机位覆盖。
	 */
	#setInstance() {
		this.#instance = null;
		this.#setCamera(this.#options.isOrthographic);
		if (this.#instance) {
			(this.#instance as ThreeCamera).position.set(10, 10, 10);
			(this.#scene as Scene).add(this.#instance);
		}
	}

	/**
	 * 创建相机实例并绑定控制器。
	 * @param isOrthographic true 使用正交相机，false 使用透视相机；形参缺省为 true，调用处均显式传值
	 */
	#setCamera(isOrthographic = true) {
		const aspect = this.#sizes.width / this.#sizes.height;
		if (isOrthographic) {
			// 正交视锥半高固定为 120，左右再按宽高比展开，
			// 这样换分辨率时地图在纵向的可视范围不变、横向按比例增减。
			const s = 120;
			this.#instance = new OrthographicCamera(
				-s * aspect,
				s * aspect,
				s,
				-s,
				1,
				10000,
			);
		} else {
			// 透视相机：45° 垂直视场角，近/远裁剪面取 1 和 10000，
			// 量级覆盖地图与远处粒子，避免被近裁剪面切掉。
			this.#instance = new PerspectiveCamera(45, aspect, 1, 10000);
		}
		this.#setControls();
	}

	/**
	 * 绑定轨道控制器。
	 * 开启阻尼后拖拽与缩放会带惯性，但必须每帧调用 update 才会生效。
	 */
	#setControls() {
		this.#controls = new OrbitControls(this.#instance as ThreeCamera, this.#canvas);
		this.#controls.enableDamping = true;
		this.#controls.update();
	}

	/**
	 * 视口尺寸变化后同步相机参数。
	 * 正交相机要重算四边边界，透视相机只改 aspect，二者都要重算投影矩阵。
	 */
	resize() {
		const aspect = this.#sizes.width / this.#sizes.height;
		if (this.#options.isOrthographic) {
			const s = 120;
			if (this.#instance instanceof OrthographicCamera) {
				this.#instance.left = -s * aspect;
				this.#instance.right = s * aspect;
				this.#instance.top = s;
				this.#instance.bottom = -s;
			}
		} else {
			if (this.#instance instanceof PerspectiveCamera) {
				this.#instance.aspect = aspect;
			}
		}
		// 投影参数只是普通字段，Three.js 不会自动感知，必须手动重算矩阵
		this.#instance?.updateProjectionMatrix();
	}
	/** 每帧推进控制器阻尼；delta 为帧间隔（秒），由 Time 的 tick 事件透传 */
	update(delta?: number) {
		this.#controls?.update(delta);
	}
	/** 解绑控制器事件监听，避免场景销毁后仍持有 canvas 引用 */
	destroy() {
		this.#controls?.dispose();
	}
}

files.src/shared/map/world-core/components/bas:
/**
 * 平面地图：用 d3-geo 的墨卡托投影把 GeoJSON 边界转成 Three.js Shape，
 * 再三角化成 ShapeGeometry 摊在 XY 平面（Z≈0），作为省级地图的底色层或高亮层。
 * 与 extrude-map 共用投影参数，通常按不同 Z 高度叠放形成「底面 + 顶面」。
 */
import { geoMercator } from "d3-geo";
import type { FeatureCollection, MultiPolygon, Position } from "geojson";
import {
	Group,
	type Material,
	Mesh,
	MeshBasicMaterial,
	Object3D,
	Shape,
	ShapeGeometry,
	Vector2,
	Vector3,
} from "three";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { transfromMapGeoJSON } from "../../utils/transfrom-map-geojson";

/** 配置占位类型：平面地图不需要额外运行时依赖 */
type BaseMapConfig = undefined;

/** 构造选项：投影中心与材质必填，其余字段从 defaultOption 继承 */
type BaseMapOption = Omit<
	typeof defaultOption,
	"geoProjectionCenter" | "material"
> & {
	geoProjectionCenter: Vector2 | number[];
	material: Material;
};

/**
 * 默认选项。
 * 填充色 0x18263b 为深蓝，配合 transparent 便于后续用 opacity 做整层淡入淡出；
 * renderOrder 1 保证地图压在网格线（-1）之上、又在描边线之下。
 */
const defaultOption = {
	position: new Vector3(0, 0, 0),
	geoProjectionCenter: new Vector2(0, 0),
	geoProjectionScale: 120,
	data: "",
	renderOrder: 1,
	merge: false,
	material: new MeshBasicMaterial({
		color: 0x18263b,
		transparent: true,
		opacity: 1,
	}),
};

/**
 * 行政区属性，对应 GeoJSON features[].properties 中的字段。
 */
export type Coordinate = {
	/** 行政区名称，同时写进 mesh.userData 供射线拾取时反查 */
	name: string;
	/** 几何中心经纬度，由数据生产方计算 */
	center: Position;
	/** 质心经纬度，比 center 更贴近视觉重心，适合放标签与柱体 */
	centroid: Position;
};

/**
 * 平面地图构建器。
 * 所有几何都落在 XY 平面，Z 由使用方通过 position 抬高，
 * 因此同一份 GeoJSON 可以叠出多层效果而不必重复生成路径。
 */
export default class BaseMap {
	/** 地图根节点，通过 setParent 挂到场景或其它 Object3D */
	#mapGroup: Group;
	/** 各行政区属性，顺序与 GeoJSON features 一致 */
	#coordinates: Coordinate[] = [];
	#option: BaseMapOption;
	/**
	 * @param _config 预留参数，当前未使用
	 * @param option 选项，未传字段用 defaultOption 补齐
	 */
	constructor(_config: BaseMapConfig, option: Partial<BaseMapOption>) {
		this.#mapGroup = new Group();
		this.#coordinates = [];
		this.#option = Object.assign({}, defaultOption, option);
		this.#mapGroup.position.copy(this.#option.position);
		const mapData = transfromMapGeoJSON(this.#option.data);
		this.create(mapData);
	}

	/** 地图根节点 */
	get mapGroup() {
		return this.#mapGroup;
	}

	/** 行政区属性列表，标签层与交互逻辑按名称从这里查经纬度 */
	get coordinates() {
		return this.#coordinates;
	}

	/**
	 * 经纬度 → 地图平面坐标。
	 * 使用墨卡托投影：center 为投影中心经纬度，scale 为缩放系数（每弧度对应的世界单位），
	 * translate 固定为 (0,0)，让投影中心恰好落在世界原点。
	 * @param args [经度, 纬度]，东经/北纬为正
	 * @returns [x, y]，单位为世界坐标；调用方通常取 (x, -y) 把屏幕 Y 轴翻成世界 Y 轴向上
	 */
	geoProjection(args: [number, number]) {
		let center: number[] = [];
		if (this.#option.geoProjectionCenter instanceof Vector2) {
			const x = this.#option.geoProjectionCenter.x;
			const y = this.#option.geoProjectionCenter.y;
			center = [x, y];
		} else {
			center = this.#option.geoProjectionCenter;
		}
		return geoMercator()
			.center(center as [number, number])
			.scale(this.#option.geoProjectionScale)
			.translate([0, 0])(args) as [number, number];
	}

	/**
	 * 根据 GeoJSON 生成地图几何。
	 * merge 为 false 时每个 feature 一个 Object3D、每个多边形环一个 Mesh；
	 * merge 为 true 时把所有环的几何合成一个 Mesh，draw call 从「环数」降到 1。
	 * @param mapData 已由 transfromMapGeoJSON 归一化的数据（Polygon 已包成 MultiPolygon）
	 */
	create(mapData: FeatureCollection) {
		const { merge } = this.#option;
		const shapes: ShapeGeometry[] = [];
		mapData.features.forEach((feature) => {
			const group = new Object3D();
			const {
				name,
				center = [],
				centroid = [],
			} = feature.properties as Coordinate;
			// 先登记属性，保证坐标顺序与 features 一致，便于按索引反查
			this.coordinates.push({ name, center, centroid });
			group.userData.name = name as string;
			(feature.geometry as MultiPolygon).coordinates.forEach((multiPolygon) => {
				multiPolygon.forEach((polygon) => {
					// 一个 Shape 对应一个多边形环（外环或内环），ShapeGeometry 负责三角剖分
					const shape = new Shape();
					for (let i = 0; i < polygon.length; i++) {
						if (!polygon[i][0] || !polygon[i][1]) {
							return;
						}
						// 投影结果沿用屏幕坐标（Y 向下），取 -y 翻成世界坐标的 Y 向上
						const [x, y] = this.geoProjection(polygon[i] as [number, number]);
						if (i === 0) {
							shape.moveTo(x, -y);
						}
						shape.lineTo(x, -y);
					}
					const geometry = new ShapeGeometry(shape);
					if (merge) {
						// 合并模式先收集几何，最后一次性 merge，把 draw call 压到 1
						shapes.push(geometry);
					} else {
						const mesh = new Mesh(geometry, this.#option.material);
						mesh.renderOrder = this.#option.renderOrder;
						mesh.userData.name = name;
						group.add(mesh);
					}
				});
			});
			if (!merge) {
				this.#mapGroup.add(group);
			}
		});
		if (merge) {
			const geometry = mergeGeometries(shapes);
			const mesh = new Mesh(geometry, this.#option.material);
			mesh.renderOrder = this.#option.renderOrder;
			this.#mapGroup.add(mesh);
		}
	}

	/** 把地图根节点挂到指定父节点（场景或某个 Group） */
	setParent(parent: Object3D) {
		parent.add(this.#mapGroup);
	}
}

files.src/shared/map/world-core/components/ext:
/**
 * 立体地图：在平面轮廓的基础上用 ExtrudeGeometry 沿 +Z 挤出厚度，
 * 顶面与侧面各用一份材质，做出省份「有厚度」的立体块。
 * 与 base-map 共用同一套墨卡托投影参数，通常叠在平面底色之上使用。
 */
import { geoMercator } from "d3-geo";
import type { FeatureCollection, MultiPolygon } from "geojson";
import {
	ExtrudeGeometry,
	Group,
	type Material,
	Mesh,
	MeshBasicMaterial,
	Object3D,
	Shape,
	Vector2,
	Vector3,
} from "three";
import type Assets from "../../assets";
import type Time from "../../utils/time";
import { transfromMapGeoJSON } from "../../utils/transfrom-map-geojson";
import type { Coordinate } from "./base-map";

/**
 * 运行时依赖。
 * assets 预留给贴图加载，time 预留给后续动态效果，当前实现均未直接使用。
 */
interface ExtrudeMapConfig {
	assets: Assets;
	time: Time;
}

/** 构造选项：投影中心与顶面/侧面材质必填，其余字段从 defaultOption 继承 */
type ExtrudeMapOption = Omit<
	typeof defaultOption,
	"geoProjectionCenter" | "topFaceMaterial" | "sideMaterial"
> & {
	geoProjectionCenter: Vector2 | number[];
	topFaceMaterial: Material;
	sideMaterial: Material;
};

/**
 * 默认选项。
 * 顶面 0x18263b、侧面 0x07152b，侧面更深以强化厚度感；
 * depth 0.1 是相对地图尺寸的挤出高度，量级与 120 的投影缩放匹配。
 */
const defaultOption = {
	position: new Vector3(0, 0, 0),
	geoProjectionCenter: new Vector2(0, 0),
	geoProjectionScale: 120,
	data: "",
	renderOrder: 1,
	topFaceMaterial: new MeshBasicMaterial({
		color: 0x18263b,
		transparent: true,
		opacity: 1,
	}),
	sideMaterial: new MeshBasicMaterial({
		color: 0x07152b,
		transparent: true,
		opacity: 1,
	}),
	depth: 0.1,
};

/**
 * 立体地图构建器。
 * 每个行政区对应一个 Object3D，组内按多边形环分别生成带厚度的 Mesh；
 * 挤出方向为 +Z，所以地图天然立在 XY 平面上，不需要额外旋转。
 */
export default class ExtrudeMap {
	/** 资源管理器，预留给贴图/材质扩展 */
	#assets: Assets;
	/** 帧循环，预留给动态效果 */
	#time: Time;
	#option: ExtrudeMapOption;
	/** 地图根节点 */
	#mapGroup: Group;
	/** 行政区属性缓存，顺序与 GeoJSON features 一致 */
	#coordinates: Coordinate[];

	/**
	 * @param config 场景级依赖（assets / time）
	 * @param option 选项，未传字段用 defaultOption 补齐
	 */
	constructor(config: ExtrudeMapConfig, option: Partial<ExtrudeMapOption>) {
		this.#mapGroup = new Group();
		this.#assets = config.assets;
		this.#time = config.time;
		this.#coordinates = [];
		this.#option = Object.assign({}, defaultOption, option);
		this.#mapGroup.position.copy(this.#option.position);

		const mapData = transfromMapGeoJSON(this.#option.data);
		this.create(mapData);
	}

	/** 行政区属性列表，供标签与交互按名称取经纬度 */
	get coordinates() {
		return this.#coordinates;
	}

	/**
	 * 经纬度 → 地图平面坐标。
	 * 与 BaseMap 保持完全一致的投影参数，两层才能严丝合缝地叠在一起。
	 * @param args [经度, 纬度]，东经/北纬为正
	 * @returns [x, y]，单位为世界坐标；使用方取 (x, -y) 翻成 Y 向上
	 */
	geoProjection(args: [number, number]) {
		let center: number[] = [];
		if (this.#option.geoProjectionCenter instanceof Vector2) {
			const x = this.#option.geoProjectionCenter.x;
			const y = this.#option.geoProjectionCenter.y;
			center = [x, y];
		} else {
			center = this.#option.geoProjectionCenter;
		}
		return geoMercator()
			.center(center as [number, number])
			.scale(this.#option.geoProjectionScale)
			.translate([0, 0])(args) as [number, number];
	}

	/**
	 * 按 feature 逐个生成挤出几何。
	 * 材质数组的顺序对应 ExtrudeGeometry 的材质分组：索引 0 为顶/底面、
	 * 索引 1 为侧面，因此传入 [topFaceMaterial, sideMaterial] 即可分别上色。
	 * @param mapData 已由 transfromMapGeoJSON 归一化的数据
	 */
	create(mapData: FeatureCollection) {
		mapData.features.forEach((feature) => {
			const group = new Object3D();
			const {
				name,
				center = [],
				centroid = [],
			} = feature.properties as Coordinate;
			this.coordinates.push({ name, center, centroid });
			// bevelEnabled 保留 1 段倒角，让轮廓转折处有细窄的斜面高光，
			// bevelThickness 与 depth 同量级，避免倒角把侧面吃掉。
			const extrudeSettings = {
				depth: this.#option.depth,
				bevelEnabled: true,
				bevelSegments: 1,
				bevelThickness: 0.1,
			};
			const materials = [
				this.#option.topFaceMaterial,
				this.#option.sideMaterial,
			];
			(feature.geometry as MultiPolygon).coordinates.forEach((multiPolygon) => {
				multiPolygon.forEach((polygon) => {
					// 一个 Shape 对应一个多边形环，ExtrudeGeometry 会沿 Z 轴扫出厚度
					const shape = new Shape();
					for (let i = 0; i < polygon.length; i++) {
						if (!polygon[i][0] || !polygon[i][1]) {
							return;
						}
						// 与平面地图一致：投影后取 -y，把屏幕坐标翻成 Y 向上
						const [x, y] = this.geoProjection(polygon[i] as [number, number]);
						if (i === 0) {
							shape.moveTo(x, -y);
						}
						shape.lineTo(x, -y);
					}

					const geometry = new ExtrudeGeometry(shape, extrudeSettings);
					// 材质数组顺序必须与 geometry 的分组索引一致，否则侧面会被贴成顶面色
					const mesh = new Mesh(geometry, materials);

					group.add(mesh);
				});
			});
			this.#mapGroup.add(group);
		});
	}

	/** 把地图根节点挂到指定父节点 */
	setParent(parent: Object3D) {
		parent.add(this.#mapGroup);
	}
}

