/**
 * 地面网格：由三部分叠加而成——GridHelper 线框、每个交点处的十字标记、
 * 覆盖全场的点阵粒子，用来表现大屏底部的「科技感网格」。
 * 与其它组件不同，它在构造时直接把自己加入场景，无需再调用 setParent。
 */
import {
	BufferAttribute,
	BufferGeometry,
	DoubleSide,
	GridHelper,
	Group,
	Mesh,
	MeshBasicMaterial,
	NormalBlending,
	Points,
	PointsMaterial,
	type Scene,
	Shape,
	ShapeGeometry,
	Vector2,
	Vector3,
} from "three";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import type Time from "../../utils/time";

/**
 * 运行时依赖。
 */
interface GridConfig {
	/** 网格直接挂载到该场景 */
	scene: Scene;
	/** 帧循环，预留给点阵动画 */
	time: Time;
}

/** 选项类型即默认选项的结构 */
type GridOption = typeof defaultOption;

/**
 * 默认选项。
 * 尺寸 100、20 等分即单格 5 个世界单位；颜色取偏青的灰，压低存在感，
 * 让地图成为视觉主体。pointLayout 是点阵的行列数，200×200 共 4 万个点。
 */
const defaultOption = {
	position: new Vector3(0, 0, 0),
	gridSize: 100,
	gridDivision: 20,
	gridColor: 0x28373a,
	shapeSize: 1,
	shapeColor: 0x8e9b9e,
	pointSize: 0.2,
	pointColor: 0x28373a,
	pointLayout: {
		row: 200,
		col: 200,
	},
	pointBlending: NormalBlending,
};

/**
 * 网格背景构建器。
 * 只在构造时生成一次静态几何并挂到场景，之后没有逐帧更新。
 */
export default class Grid {
	#scene: Scene;
	#time: Time;
	#option: GridOption;

	/** 网格根节点，构造完成后一定存在，故使用明确赋值断言 */
	#instance!: Group;

	/**
	 * @param config 场景与帧循环
	 * @param option 尺寸、颜色等覆盖值
	 */
	constructor(config: GridConfig, option?: Partial<GridOption>) {
		this.#scene = config.scene;
		this.#time = config.time;
		this.#option = Object.assign({}, defaultOption, option);
		this.init();
	}

	/** 取网格根节点，可用于整体显隐或替换位置 */
	get instance() {
		return this.#instance;
	}

	/** 组装线框、十字标记与点阵三部分，整体按 option.position 平移后加入场景 */
	init() {
		const group = new Group();
		group.name = "Grid";
		const grid = this.createGridHelp();
		const shapes = this.createShapes();
		const points = this.createPoint();
		group.add(grid, shapes, points);
		group.position.copy(this.#option.position);
		this.#instance = group;
		this.#scene.add(group);
	}

	/**
	 * 在每个网格交点放置十字标记。
	 * 先由 gridSize / gridDivision 算出格距，遍历 (division+1)² 个交点，
	 * 每个十字单独生成几何后统一 merge，最终只剩一个 draw call。
	 * @returns 已旋转到 XZ 平面并抬高 0.01 的单个 Mesh
	 */
	createShapes() {
		const { gridSize, gridDivision, shapeSize, shapeColor } = this.#option;
		const shapeSpace = gridSize / gridDivision;
		// range 是半边长，平移时以原点为中心向两侧铺开
		const range = gridSize / 2;
		const shapeMaterial = new MeshBasicMaterial({
			color: shapeColor,
			side: DoubleSide,
		});
		const shapeGeometrys = [];
		for (let i = 0; i < gridDivision + 1; i++) {
			for (let j = 0; j < gridDivision + 1; j++) {
				const shapeGeometry = this.createPlus(shapeSize);
				shapeGeometry.translate(
					-range + i * shapeSpace,
					-range + j * shapeSpace,
					0,
				);
				shapeGeometrys.push(shapeGeometry);
			}
		}
		const geometry = mergeGeometries(shapeGeometrys);
		const shapeMesh = new Mesh(geometry, shapeMaterial);
		// renderOrder 只决定绘制顺序、不改变深度关系；-1 让十字标记最先画，
		// 作为整个场景最底层的装饰
		shapeMesh.renderOrder = -1;
		// XY 平面上的十字绕 X 轴转 -90° 摊平到 XZ 平面，
		// 再抬高 0.01 避免与网格线共面产生 z-fighting 闪烁
		shapeMesh.rotateX(-Math.PI / 2);
		shapeMesh.position.y += 0.01;
		return shapeMesh;
	}

	/**
	 * 生成基础线框网格：每个轴向 division 等分（即 division+1 条线），
	 * 位于 XZ 平面、Y=0；横竖线同色，只保留细线带来的「坐标纸」质感。
	 */
	createGridHelp() {
		const { gridSize, gridDivision, gridColor } = this.#option;
		const gridHelp = new GridHelper(
			gridSize,
			gridDivision,
			gridColor,
			gridColor,
		);
		return gridHelp;
	}

	/**
	 * 生成覆盖全场的点阵。
	 * 顶点按行优先排列，索引 = (i * cols + j) * 3，i 沿 X 轴、j 沿 Z 轴，
	 * 均匀铺满 [-gridSize/2, gridSize/2]；Y 恒为 0，与网格平面共面。
	 * @returns 带 position 属性的 Points 对象，材质使用 sizeAttenuation 让近大远小
	 */
	createPoint() {
		const { gridSize, pointSize, pointColor, pointBlending, pointLayout } =
			this.#option;
		const rows = pointLayout.row;
		const cols = pointLayout.col;
		// 每个顶点 3 个分量（x/y/z），整块一次性分配，避免循环里反复扩容
		const positions = new Float32Array(rows * cols * 3);
		for (let i = 0; i < rows; i++) {
			for (let j = 0; j < cols; j++) {
				// rows - 1 / cols - 1 做分母，首尾点正好落在场地的两条边界上
				const x = (i / (rows - 1)) * gridSize - gridSize / 2;
				const y = 0;
				const z = (j / (cols - 1)) * gridSize - gridSize / 2;
				// 索引是顶点序号，写入时要乘 3 换算成分量偏移
				const index = (i * cols + j) * 3;
				positions[index] = x;
				positions[index + 1] = y;
				positions[index + 2] = z;
			}
		}
		const geometry = new BufferGeometry();
		geometry.setAttribute("position", new BufferAttribute(positions, 3));
		const material = new PointsMaterial({
			size: pointSize,
			sizeAttenuation: true,
			color: pointColor,
			blending: pointBlending,
		});
		const particles = new Points(geometry, material);

		return particles;
	}

	/** 预留：切换点阵的显示模式，当前未实现，调用无副作用 */
	setPointMode() {}

	/**
	 * 构造单个十字轮廓（两个互相垂直的细长矩形拼成）。
	 * @param shapeSize 十字的尺寸基准，默认 50；臂宽 w = size/18，臂半长 h = size/3
	 * @returns 位于 XY 平面、以原点为中心的 ShapeGeometry，曲线分段数 24
	 */
	createPlus(shapeSize = 50) {
		const w = shapeSize / 6 / 3;
		const h = shapeSize / 3;
		// 顶点按顺序给出 13 个点，Shape 自动闭合首尾，共 13 条边
		const points = [
			new Vector2(-h, -w),
			new Vector2(-w, -w),
			new Vector2(-w, -h),
			new Vector2(w, -h),
			new Vector2(w, -h),
			new Vector2(w, -w),
			new Vector2(h, -w),
			new Vector2(h, w),
			new Vector2(w, w),
			new Vector2(w, h),
			new Vector2(-w, h),
			new Vector2(-w, w),
			new Vector2(-h, w),
		];
		const shape = new Shape(points);
		const shapeGeometry = new ShapeGeometry(shape, 24);
		return shapeGeometry;
	}
}

files.src/shared/map/world-core/components/lab:
/**
 * CSS3D 标签层：用 CSS3DRenderer 把真实 DOM 元素按 3D 坐标投影到屏幕上，
 * 得到可换行、可加样式的地图标注。它叠在 WebGL canvas 之上单独渲染一层，
 * 与主渲染器共用同一个 Scene 与相机，因此标签会跟随地图一起缩放与旋转。
 */
import type { Object3D, Scene } from "three";
import { CSS3DRenderer } from "three/examples/jsm/renderers/CSS3DRenderer.js";
import type { Sizes } from "../../utils/sizes";
import type Time from "../../utils/time";
import { uuid } from "../../utils/uuid";
import type Camera from "../camera";
import type { CameraConfig } from "../camera";
import CSS3DObject from "../extensions/css-3d-object";
import CSS3DSprite from "../extensions/css-3d-sprite";

/**
 * 标签层初始化配置：在相机配置基础上补充相机包装与帧循环。
 */
interface Label3DConfig extends CameraConfig {
	/** 相机控制器，CSS3D 渲染需要与 WebGL 用同一相机 */
	camera: Camera;
	/** 帧循环，标签层逐帧同步渲染 */
	time: Time;
}

/** 标签对象：普通朝向（CSS3DObject）或始终面向相机（CSS3DSprite） */
export type Label = CSS3DObject | CSS3DSprite;

/**
 * CSS3D 标签管理器。
 * 除创建 / 移除标签外，还负责把 CSS3D 的 DOM 层与 canvas 对齐，
 * 并订阅 resize 与 tick，保证尺寸和相机变化时标签不漂移。
 */
export default class Label3D {
	#canvas: HTMLCanvasElement;
	#sizes: Sizes;
	#scene: Scene;
	#camera: Camera;
	#time: Time;
	/** 最近一次 setParent 指定的父节点，remove 时从这里摘除 */
	#parent: Object3D | null;
	#css3DRenderer: CSS3DRenderer;

	/**
	 * 创建 CSS3D 渲染器，并把它的 DOM 层插入到与 canvas 同级的位置。
	 */
	constructor(config: Label3DConfig) {
		this.#canvas = config.canvas;
		this.#sizes = config.sizes;
		this.#scene = config.scene;
		this.#camera = config.camera;
		this.#time = config.time;
		this.#parent = null;
		const { width, height } = this.#sizes;
		this.#css3DRenderer = new CSS3DRenderer();
		this.#css3DRenderer.setSize(width, height);
		// 绝对定位铺满 canvas，zIndex 9999 保证标签浮在所有画布元素之上
		this.#css3DRenderer.domElement.style.position = "absolute";
		this.#css3DRenderer.domElement.style.top = "0px";
		this.#css3DRenderer.domElement.style.left = "0px";
		// 标签是纯展示层，默认不接收鼠标事件，避免挡住地图的拖拽与 hover
		this.#css3DRenderer.domElement.style.pointerEvents = "none";
		this.#css3DRenderer.domElement.style.zIndex = "9999";
		// 用 uuid 生成唯一 class，多实例时可在样式或调试中区分各自的 DOM 层
		this.#css3DRenderer.domElement.className = `label3d-${uuid()}`;
		this.#canvas.parentNode?.appendChild(this.#css3DRenderer.domElement);
		// 每帧重新渲染，标签的屏幕坐标才会跟随相机变化
		this.#time.on("tick", () => {
			this.update();
		});
		this.#sizes.on("resize", () => {
			this.resize();
		});
	}

	/**
	 * 创建一个标签节点并包装成 CSS3D 对象。
	 * @param content 初始 HTML 字符串，后续可通过 label.init 覆盖
	 * @param className 自定义样式类；为空时套用内置的暗色圆角气泡样式
	 * @param isSprite true 使用 CSS3DSprite，标签始终正对相机；false 则跟随父级朝向
	 * @returns 扩展过 init / hide / show / setParent 等便捷方法的标签对象
	 */
	create(content = "", className = "", isSprite = false) {
		const tag = document.createElement("div");
		tag.innerHTML = content;
		tag.className = className;
		// 先隐藏，待调用方 init / setParent 后再显示，避免在默认位置闪一下
		tag.style.visibility = "hidden";
		tag.style.position = "absolute";
		if (!className) {
			tag.style.padding = "10px";
			tag.style.color = "#fff";
			tag.style.fontSize = "12px";
			tag.style.textAlign = "center";
			tag.style.background = "rgba(0,0,0,0.6)";
			tag.style.borderRadius = "4px";
		}
		let label: Label;
		// 两种包装只差朝向逻辑：Object 跟随父级旋转，Sprite 始终面向相机
		if (!isSprite) {
			label = new CSS3DObject(tag);
		} else {
			label = new CSS3DSprite(tag);
		}
		// 把 DOM 操作收敛到标签对象上，调用方不必再关心 CSS3D 内部结构
		label.init = (content, position) => {
			label.element.innerHTML = content;
			label.element.style.visibility = "visible";
			label.position.copy(position);
		};
		label.hide = () => {
			label.element.style.visibility = "hidden";
		};
		label.scaleHide = () => {
			label.element.classList.add("scale-hidden");
		};
		label.show = () => {
			label.element.style.visibility = "visible";
			label.element.classList.remove("scale-hidden");
		};
		label.setParent = (parent) => {
			this.#parent = parent;
			parent.add(label);
		};
		label.remove = () => {
			this.#parent?.remove(label);
			return label;
		};
		return label;
	}

	/**
	 * 统一设置标签的缩放、朝向与鼠标穿透。
	 * @param scale 统一缩放，默认 0.1：CSS3D 中 1 个世界单位等于 1 像素，
	 * 缩到 0.1 才能与地图的比例匹配，否则标签会大得离谱
	 * @param axis 绕哪根轴旋转，默认 x 轴——把竖直的 DOM 平面放平贴到地图上
	 * @param axisRotation 旋转弧度，默认 90°
	 * @param pointerEvents CSS 的 pointer-events 取值，默认 none 不拦截交互
	 */
	setLabelStyle(
		label: Label,
		scale = 0.1,
		axis: "x" | "y" | "z" = "x",
		axisRotation = Math.PI / 2,
		pointerEvents = "none",
	) {
		label.element.style.pointerEvents = pointerEvents;
		label.scale.set(scale, scale, scale);
		// 控制 HTML 标签在 3D 空间中的朝向，使其贴合地图平面
		switch (axis) {
			case "x":
				label.rotation.x = axisRotation;
				break;
			case "y":
				label.rotation.y = axisRotation;
				break;
			case "z":
				label.rotation.z = axisRotation;
				break;
			default:
				// 如果传入了无效的轴，默认使用 x 轴
				label.rotation.x = axisRotation;
				break;
		}
	}

	/** 调整 CSS3D 图层的 z-index，用于与其它 DOM 浮层重新排序 */
	setRenderLevel(zIndex: string) {
		this.#css3DRenderer.domElement.style.zIndex = zIndex;
	}

	/** 每帧调用：以同一相机重新渲染 CSS3D 场景，让标签跟随视图变换 */
	update() {
		this.#css3DRenderer.render(this.#scene, this.#camera.instance);
	}

	/** 视口变化时同步 CSS3D 渲染器尺寸，否则标签的投影位置会整体偏移 */
	resize() {
		const { width, height } = this.#sizes;
		this.#css3DRenderer.setSize(width, height);
	}

	/** 移除 CSS3D 层的 DOM 节点，场景中已创建的标签随之不再显示 */
	destroy() {
		if (this.#css3DRenderer) {
			const domElement = this.#css3DRenderer.domElement;
			domElement.parentNode?.removeChild(domElement);
		}
	}
}

